={{
(() => {
  const text = (($('Switch').first().json.post_text ?? '')
    .replace(/\\n/g, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .substring(0, 1800))
    + '\n\n<a href="https://max.ru/gotovimdoma_max">📸 Подпишись на лучшие рецепты</a>';

  const photos = $('Merge13').first().json.photos ?? {};

  const attachments = Object.entries(photos).map(([photoKey, photoValue]) => ({
    type: 'image',
    payload: {
      photos: {
        [photoKey]: photoValue
      }
    }
  }));

  return {
    text,
    format: 'html',
    attachments
  };
})()
}}
